using System.Globalization;
using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Nodes;
using NUnit.Framework;

namespace FactsPDF.Tests.UaDefaults;

/// <summary>
/// FactsPDF's resolved element defaults against Chrome's user-agent stylesheet. The corpus holds one
/// synthetic probe per supported element; <c>chrome-computed.json</c> is a committed snapshot of
/// Chrome's getComputedStyle for each probe element (regenerated by
/// <c>scripts/ua_defaults_browser_differential.py</c>); <c>known-differences.json</c> lists every
/// difference that exists today. The test fails on a difference that is not listed and on a listed
/// difference that no longer occurs, so the list can only shrink.
/// </summary>
[TestFixture]
public sealed class UaDefaultsTests
{
    private const string NotModelled = "(not modelled)";
    private const string UpdateVariable = "FACTSPDF_UA_UPDATE";
    private const double LengthTolerance = 0.05;

    // The element names of the HTML Standard's element index plus the obsolete ones browsers still know:
    // the universe the coverage guard asks FactsPDF's own element predicates about.
    private static readonly string[] HtmlElementNames =
    [
        "a", "abbr", "acronym", "address", "applet", "area", "article", "aside", "audio", "b", "base", "basefont", "bdi", "bdo",
        "bgsound", "big", "blink", "blockquote", "body", "br", "button", "canvas", "caption", "center", "cite", "code", "col",
        "colgroup", "data", "datalist", "dd", "del", "details", "dfn", "dialog", "dir", "div", "dl", "dt", "em", "embed",
        "fieldset", "figcaption", "figure", "font", "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6",
        "head", "header", "hgroup", "hr", "html", "i", "iframe", "img", "input", "ins", "kbd", "label", "legend", "li", "link",
        "listing", "main", "map", "mark", "marquee", "menu", "meta", "meter", "nav", "nobr", "noembed", "noframes", "noscript",
        "object", "ol", "optgroup", "option", "output", "p", "param", "picture", "plaintext", "pre", "progress", "q", "rb", "rp",
        "rt", "rtc", "ruby", "s", "samp", "script", "search", "section", "select", "slot", "small", "source", "span", "strike",
        "strong", "style", "sub", "summary", "sup", "svg", "table", "tbody", "td", "template", "textarea", "tfoot", "th",
        "thead", "time", "title", "tr", "track", "tt", "u", "ul", "var", "video", "wbr", "xmp",
    ];

    private static bool Supported(string name)
        => HtmlDocumentReader.ParagraphTag(name) || HtmlDocumentReader.Container(name) || HtmlDocumentReader.InlineTag(name)
            || TableMarkup.IsTag(name) || HtmlDocumentReader.VoidInlineTag(name) || HtmlDocumentReader.ReplacedTag(name)
            || HtmlDocumentReader.HiddenTag(name) || name is "img" or "svg" or "hr" or "br";

    private static readonly JsonSerializerOptions Compact = new() { Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping };

    [Test]
    public void EverySupportedElementHasAProbe()
    {
        var probed = UaCorpus.Load().Probes.SelectMany(p => p.Targets).Select(t => UaProbe.ParseTarget(t).Tag).ToHashSet();
        var unprobed = HtmlElementNames.Where(Supported).Where(name => !probed.Contains(name)).ToList();
        Assert.That(unprobed, Is.Empty, "Supported elements with no probe in tests/fixtures/ua-defaults/corpus.json");
    }

    [Test]
    public void EveryProbedElementIsStillSupported()
    {
        var probed = UaCorpus.Load().Probes.SelectMany(p => p.Targets).Select(t => UaProbe.ParseTarget(t).Tag).Distinct();
        Assert.That(probed.Where(name => !Supported(name) && name is not "html"), Is.Empty,
            "Probed elements FactsPDF no longer supports: drop their probes");
    }

    [Test]
    public void SnapshotAndCorpusDescribeTheSameElements()
    {
        var snapshot = Snapshot();
        var corpusKeys = UaCorpus.Load().Probes.SelectMany(p => p.Targets.Select(t => p.Id + "/" + t)).Order(StringComparer.Ordinal);
        Assert.That(snapshot.Elements.Keys.Order(StringComparer.Ordinal), Is.EqualTo(corpusKeys));
        Assert.That(snapshot.Properties, Is.EqualTo(UaDefaultsModel.Properties));
    }

    [Test]
    public void ComputedDefaultsMatchChromeExceptKnownDifferences()
    {
        var corpus = UaCorpus.Load();
        var snapshot = Snapshot();
        var found = new List<Difference>();
        foreach (var probe in corpus.Probes)
        {
            var model = new UaDefaultsModel(corpus.Html(probe), Options(corpus));
            foreach (var target in probe.Targets)
            {
                var key = probe.Id + "/" + target;
                var resolved = model.Resolve(target);
                foreach (var property in UaDefaultsModel.Properties)
                {
                    var chrome = snapshot.Elements[key][property];
                    var factspdf = resolved[property];
                    if (!Matches(property, chrome, factspdf)) found.Add(new(key, property, chrome, factspdf ?? NotModelled));
                }
            }
        }

        var known = ReadKnown();
        if (Environment.GetEnvironmentVariable(UpdateVariable) == "1")
        {
            WriteComputedSection(found, known);
            Assert.Inconclusive($"Rewrote the computed section of known-differences.json with {found.Count} differences.");
        }

        var unlisted = found.Where(d => !known.Any(k => k.Same(d))).ToList();
        var stale = known.Where(k => !found.Any(k.Same)).ToList();
        var unclassified = known.Where(k => string.IsNullOrWhiteSpace(k.Reason) || k.Reason == "unclassified").ToList();
        Assert.Multiple(() =>
        {
            Assert.That(unlisted.Select(Describe), Is.Empty, "Differences from Chrome that are not in known-differences.json");
            Assert.That(stale.Select(Describe), Is.Empty, "Listed differences that no longer occur: remove them");
            Assert.That(unclassified.Select(Describe), Is.Empty, "Listed differences need a one-line reason");
        });
    }

    private static string Describe(Difference d) => $"{d.Element} {d.Property}: Chrome {d.Chrome}, FactsPDF {d.FactsPdf}";

    private static PdfOptions Options(UaCorpus corpus)
        => new() { Images = new Dictionary<string, PdfImage> { [corpus.ImageName] = PdfImage.FromBytes(PngFixture.Image([0, 80, 100], type: 0)) } };

    // A property FactsPDF does not model on an element keeps the CSS initial value, so it differs from Chrome
    // only where Chrome's user-agent sheet sets a different one.
    private static bool Matches(string property, string chrome, string? factspdf)
    {
        factspdf ??= UaDefaultsModel.Initial[property];
        if (chrome.EndsWith("pt", StringComparison.Ordinal) && factspdf.EndsWith("pt", StringComparison.Ordinal))
            return Math.Abs(Pt(chrome) - Pt(factspdf)) <= LengthTolerance;
        return chrome == factspdf;
    }

    private static double Pt(string value) => double.Parse(value[..^2], CultureInfo.InvariantCulture);

    private sealed record Difference(string Element, string Property, string Chrome, string FactsPdf, string Reason = "")
    {
        internal bool Same(Difference other)
            => Element == other.Element && Property == other.Property && Chrome == other.Chrome && FactsPdf == other.FactsPdf;
    }

    private sealed record ChromeSnapshot(string[] Properties, Dictionary<string, Dictionary<string, string>> Elements);

    private static ChromeSnapshot Snapshot()
    {
        var root = JsonNode.Parse(File.ReadAllText(Path.Combine(UaCorpus.FixtureDirectory(false), "chrome-computed.json")))!;
        return new(
            [.. root["properties"]!.AsArray().Select(p => p!.GetValue<string>())],
            root["elements"]!.AsObject().ToDictionary(
                e => e.Key,
                e => e.Value!.AsObject().ToDictionary(p => p.Key, p => p.Value!.GetValue<string>())));
    }

    private static List<Difference> ReadKnown()
    {
        var root = JsonNode.Parse(File.ReadAllText(Path.Combine(UaCorpus.FixtureDirectory(false), "known-differences.json")))!;
        return [.. root["computed"]!.AsArray().Select(e => new Difference(
            e!["element"]!.GetValue<string>(), e["property"]!.GetValue<string>(), e["chrome"]!.GetValue<string>(),
            e["factspdf"]!.GetValue<string>(), e["reason"]!.GetValue<string>()))];
    }

    // Rewrites only the computed section, keeping each difference's reason and the geometry section verbatim.
    private static void WriteComputedSection(List<Difference> found, List<Difference> known)
    {
        var path = Path.Combine(UaCorpus.FixtureDirectory(true), "known-differences.json");
        var root = JsonNode.Parse(File.ReadAllText(path))!;
        var geometry = root["geometry"]!.AsArray().Select(e => e!.ToJsonString(Compact)).ToList();
        var builder = new StringBuilder("{\n \"computed\":[\n");
        builder.AppendJoin(",\n", found.Select(d => "  " + new JsonObject
        {
            ["element"] = d.Element,
            ["property"] = d.Property,
            ["chrome"] = d.Chrome,
            ["factspdf"] = d.FactsPdf,
            ["reason"] = known.FirstOrDefault(k => k.Same(d))?.Reason ?? "unclassified",
        }.ToJsonString(Compact)));
        builder.Append("\n ],\n \"geometry\":[\n");
        builder.AppendJoin(",\n", geometry.Select(g => "  " + g));
        builder.Append("\n ]\n}\n");
        File.WriteAllText(path, builder.ToString(), new UTF8Encoding(false));
    }
}
